import { get, size, debounce } from 'lodash'
import { useCallback, useEffect, useRef, useState } from 'react'
import { BottomActionContainerStyle, DisplayCircleIcon, Row } from '../../../../../../commonStyle/index.style'
import { Container, CustomText } from '../../../../../../components'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import CircularLoader from '../../../../../../components/CircularLoader'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { INSTANT_PAYOUT_POLICIES } from '../../../../../../constants/cookies'
import { useLoaderContextValue, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { getFromLocalStorageData, removeFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { formatMoney, getQueryParams } from '../../../../../../helpers/utility'
import { FILE_GOLD, INFO } from '../../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import EmptyList from '../../../../../../components/EmptyList'
import OfflinePolicyCard from '../../../components/OfflinePolicyCard'
import { useGetFilterOfflinePolicies, useGetOfflinePolicies, useGetTotalBill, useInstantPayoutBalance } from '../../../state/hooks/useInstantPayout'
import { InstantPayoutBalanceStyle, InstantPolicyListStyle } from './index.style'
import { EXCLUDE_PRODUCT_KEY } from '../../../../Policy/constants'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext'

function PayoutContainer (props) {
  const { history } = props
  const [
    {
      getOfflinePoliciesData = [],
      getOfflinePoliciesMetaData = {}
    },
    getOfflinePolicies
  ] = useGetOfflinePolicies()
  const [
    {
      getFilterOfflinePoliciesData = [],
      getFilterOfflinePoliciesMetaData = {}
    },
    getFilterOfflinePolicies
  ] = useGetFilterOfflinePolicies()
  const [{ instantPayoutBalanceData = {} }, getInstantPayoutBalance] = useInstantPayoutBalance()
  const [totalBill] = useGetTotalBill(0)
  const listParams = useRef({
    query: {
      page: 1,
      page_size: 5
    }
  })
  const loaderRef = useRef(null)
  const observer = useRef(null)
  const isInitialCall = useRef(false)
  const loaderState = useRef({})
  const [{ GET_OFFLINE_POLICIES_LOADER }] = useLoaderContextValue()
  const [{ GET_OFFLINE_POLICIES_ERROR }] = useErrorContextValue()
  const [{ getAgentDetailData }] = useGlobalContextValue()
  const [showFilterData, setShowFilterData] = useState(false)

  // handleInfiniteLoading(entries, loaderRef.current, loadOfflinePoliciesProof)

  useEffect(() => {
    return () => {
      removeFromLocalStorageData('INSTANT_PAYOUT_POLICIES')
    }
  }, [])

  useEffect(() => {
    // we want to call this function only first time
    const handleObserver = (entities) => {
      const y = entities[0].boundingClientRect.y
      if (loaderState.current.prevY > y &&
        (listParams.current.query.page < getOfflinePoliciesMetaData.num_page ||
           listParams.current.query.page < getFilterOfflinePoliciesMetaData.num_page)) {
        listParams.current.query.page = listParams.current.query.page + 1
        const query = {
          ...listParams.current.query,
          exclude_product_online: EXCLUDE_PRODUCT_KEY.join(',')
        }
        getOfflinePolicies({ query })
      }
      loaderState.current.prevY = y
    }

    var options = {
      root: null,
      rootMargin: '0px',
      threshold: 1.0
    }

    observer.current = new IntersectionObserver(
      handleObserver,
      options
    )
    if (!GET_OFFLINE_POLICIES_ERROR && !GET_OFFLINE_POLICIES_LOADER &&
      !get(showFilterData ? getFilterOfflinePolicies : getOfflinePoliciesData, 'length', 0) &&
      !isInitialCall.current) {
      // URL is being used in email where application_id is  being used to limit the policies
      const applicationId = getQueryParams('application_id')
      let query = {}
      if (applicationId) {
        query.application_id = applicationId
      }

      query = {
        ...query,
        ...listParams.current.query,
        exclude_product_online: EXCLUDE_PRODUCT_KEY.join(',')
      }
      isInitialCall.current = true
      getInstantPayoutBalance()
      getOfflinePolicies({ query })
    }

    if (loaderRef.current) {
      observer.current.observe(loaderRef.current)
    }

    return () => {
      observer.current.disconnect()
    }
  }, [
    getInstantPayoutBalance, getOfflinePoliciesData, showFilterData, getFilterOfflinePoliciesMetaData,
    getOfflinePolicies, getOfflinePoliciesMetaData, getFilterOfflinePolicies,
    GET_OFFLINE_POLICIES_LOADER, GET_OFFLINE_POLICIES_ERROR
  ])

  const handleToProofPage = useCallback(() => {
    const policy = getFromLocalStorageData(INSTANT_PAYOUT_POLICIES)
    if (!getAgentDetailData.is_ktp_verified && (Object.values(policy)[0].payment_by === 'AGENT')) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: LANG_STRINGS.yourKtpMustVerifiedForThePayment
        })
      }
      return
    }
    history.push({
      pathname: '/instant/payout/transactions/proof',
      state: {
        policies: policy,
        totalBill
      }
    })
    // remove the data from the localStorage if user comes to this page
    removeFromLocalStorageData(INSTANT_PAYOUT_POLICIES)
  }, [history, totalBill, getAgentDetailData.is_ktp_verified])

  const handleSearch = (val) => {
    if (val.length > 0) {
      setShowFilterData(true)
      if (val.length > 2) {
        getFilterOfflinePolicies({
          query: {
            search_text: val
          }
        })
      }
    } else {
      setShowFilterData(false)
    }
  }

  return (
    <Container
      title={LANG_STRINGS.totalBill}
      loader={GET_OFFLINE_POLICIES_LOADER}
      onSearch={debounce(handleSearch, 500)}
      searchPlaceHolder={LANG_STRINGS.searchForTransactions}
      hideBottomTabs
      showSearchBar
    >
      <InstantPayoutBalanceStyle
        align='center'
        limit={instantPayoutBalanceData.is_active && instantPayoutBalanceData.remaining_balance}
      >
        {
          (instantPayoutBalanceData.is_active && instantPayoutBalanceData.remaining_balance) && (
            <>
              <DisplayCircleIcon className='payout-info-icon' bgColor={AgentColorPallette.white}>
                <img src={INFO} alt='' />
              </DisplayCircleIcon>
              <CustomText color={AgentColorPallette.darkCharcoal} size='14px'>
                {`${LANG_STRINGS.instantPayoutBalance} ${formatMoney(instantPayoutBalanceData.remaining_balance, 0)}`}
              </CustomText>
            </>
          )
        }
      </InstantPayoutBalanceStyle>
      {
        showFilterData ? (
          <InstantPolicyListStyle>
            {
              getFilterOfflinePoliciesData.map(policy => (
                <OfflinePolicyCard
                  key={policy.id}
                  id={`offlinePolicies-${policy.id}`}
                  policy={policy}
                />
              ))
            }
            {
              !!totalBill && (
                <BottomActionContainerStyle
                  direction='column'
                  padding='0'
                  bgColor='transparent'
                  align='stretch'
                >
                  <Row justify='space-between' align='center' className='policies-total-bill'>
                    <CustomText weight={800} size='14px'>
                      {LANG_STRINGS.totalBill}
                    </CustomText>
                    <CustomText weight={800} size='14px'>
                      {formatMoney(totalBill, 0)}
                    </CustomText>

                  </Row>
                  <div className='send-proof-payment'>
                    <ButtonWithIcon
                      text={LANG_STRINGS.sendProofPayment}
                      icon={FILE_GOLD}
                      onClick={handleToProofPage}
                      iconRight
                    />
                  </div>
                </BottomActionContainerStyle>
              )
            }
          </InstantPolicyListStyle>
        ) : size(getOfflinePoliciesData) ? (
          <InstantPolicyListStyle>
            {
              getOfflinePoliciesData.map(policy => (
                <OfflinePolicyCard
                  key={policy.id}
                  id={`offlinePolicies-${policy.id}`}
                  policy={policy}
                />
              ))
            }
            {
              !!get(getOfflinePoliciesData, 'length', 0) && (get(getOfflinePoliciesMetaData, 'num_page', 0) !== listParams.current.query.page) &&
              (
                <div id='policies-list-loader' className='policy-loader' ref={loaderRef}>
                  <CircularLoader isLoading />
                </div>
              )

            }
            {
              !!totalBill && (
                <BottomActionContainerStyle
                  direction='column'
                  padding='0'
                  bgColor='transparent'
                  align='stretch'
                >
                  <Row justify='space-between' align='center' className='policies-total-bill'>
                    <CustomText weight={800} size='14px'>
                      {LANG_STRINGS.totalBill}
                    </CustomText>
                    <CustomText weight={800} size='14px'>
                      {formatMoney(totalBill, 0)}
                    </CustomText>
                  </Row>
                  <div className='send-proof-payment'>
                    <ButtonWithIcon
                      text={LANG_STRINGS.sendProofPayment}
                      icon={FILE_GOLD}
                      onClick={handleToProofPage}
                      iconRight
                    />
                  </div>
                </BottomActionContainerStyle>
              )
            }
            <ShowSnackbar hideOkay />
          </InstantPolicyListStyle>
        ) : (GET_OFFLINE_POLICIES_LOADER === false) && <EmptyList height='102px' content={ERROR_LANG.emptyOfflinePolicy} />
      }
    </Container>
  )
}

export default PayoutContainer
